from pathlib import Path
import re,json
root=Path(__file__).resolve().parents[1]
notes=['定义应突出对流层低层局地风速极大带；850—700 hPa及12—15 m/s为特定天气分析经验，本题未给这些数值。边界层急流与较高层天气尺度低空急流成因不同，不能统一归因夜间惯性振荡。', '南亚高压的上对流层暖性反气旋、季风区和高原加热背景描述正确；常在100—200 hPa附近分析，具体层次随资料而变。不能与500 hPa西太副高或地面热低压合并成同一中心。', '南方涛动为热带太平洋东西部大尺度气压反相变化，塔希提减达尔文的标准化压差负异常常对应厄尔尼诺。应说明指数符号约定，不能用单日气压异常判定完整ENSO事件。', '阳伞效应主要指散射或反射短波减少地表太阳能输入。吸收气溶胶可使所在大气层增温，云调整又依环境而异，不能把所有气溶胶作用都概括为全球均匀冷却。', '地面对空气应力约定下抽吸负旋度公式正确，依赖常ρ、常f、层顶应力趋零和底部无穿透。若采用空气对地面或海洋表面应力，须重新核对方向；Ri和Re不属于抽吸定义核心。', '斜压不稳定的有效位能取能链与暖升冷沉转换符号正确。典型向西倾斜是所讨论中纬基本流和增长阶段的结构，非所有斜压扰动通用几何规则；有垂直切变不自动构成充分不稳定判据。', '分开列源地、蓄积区和进入我国路径；本题问冷空气，不是每次过程都达到寒潮标准。西路、西北路、东路是常用概括，具体地形绕流、汇合路径依个例而变。', '水汽、抬升、持续时间及较高降水效率是主线；强条件不稳定有助对流暴雨，但层状降水也能累计成暴雨。切变和训练效应是组织/持续机制，不能把大风切变当任意暴雨必需条件。', '原卷标“略，不用写”，本条仅核对任务范围，保留为拓展阅读，不计新增必做题。气体列表与辐射公式如需作为正式答案，应另作对应资料复核。', '非地转风表达式叉积方向正确。它促进辐合辐散和质量调整，但“地转风无散”需限定常f等压面模型；β平面不能无条件把全部散度归于非地转风。', '已按题给两式逐步消元，位势倾向与ω方程符号一致；须取平流风为地转风、f0常数、$\\sigma=\\sigma(p)>0$且不随水平位置变化。令$\\chi=\\frac{\\partial\\Phi}{\\partial t}$，B是位势垂直梯度的平流，转成温度平流时有负号。倾向方程保留σ的垂直变化，不能把$\\frac{\\partial}{\\partial p}(\\frac{1}{\\sigma}\\frac{\\partial\\chi}{\\partial p})$随意简成常系数。正强迫对应上升的说明限相应模态/边界条件，实际须求解整个椭圆问题。', '形成过程和江淮降水、大风、降温影响均已覆盖。需画或写高空槽相对地面低压的配置，再说明暖湿输送、锋区斜压性和潜热反馈；不能仅以“有高空槽”作为气旋必加深的充分条件。', '原卷标“略，不用写”，仅核对任务范围，保留拓展内容。题目泛指大地形而原解主要举青藏高原，若以后列为必做题需补其他地形实例并区分天气与气候；原解“四种以上”不是本题要求。']
source=root.parent/'动力气象课后习题/试题解答/往年试题解析/2012.md'
ids=re.findall(r'^## 题目 (.+)$',source.read_text(encoding='utf-8'),re.M)
assert len(ids)==len(notes)
review=dict(zip(ids,notes))
(root/'scripts/review_2012.json').write_text(json.dumps(review,ensure_ascii=False,indent=2),encoding='utf-8')
for p in (root/'每日内容').glob('D*.md'):
 s=p.read_text(encoding='utf-8')
 for q,note in review.items():
  pattern=r'^(### '+re.escape(q)+r'[^\n]*)\n(?:\n\*\*本次复核提示（2026-11-01）：\*\* [^\n]*\n)?'
  s=re.sub(pattern,lambda m:m[1]+'\n\n**本次复核提示（2026-11-01）：** '+note+'\n',s,flags=re.M)
 p.write_text(s,encoding='utf-8')
p=root/'逐题复核记录.md';s=p.read_text(encoding='utf-8').replace('2010及2011年共261条记录','2010、2011及2012年共274条记录').replace('1条原卷标略仅核对任务范围','3条原卷标略仅核对任务范围').replace('其余275题','其余262题')
lines=[]
for line in s.splitlines():
 m=re.match(r'\| \[([^\]]+)\]',line)
 if m and m[1] in review:
  line=line.replace('结构核对完成；学科内容待复核','原卷标略：仅核对任务范围' if m[1] in ['2012-二-3','2012-四-2'] else '内容复核（2026-11-01）').replace('仅核对题号、题干/解答段落，未据此宣称答案正确。',review[m[1]].replace('|',r'\|'))
 lines.append(line)
p.write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Reviewed',len(review),'questions')
